window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-7e37bb7fd484dfd0"]={"versions": [{"id": "FIG-7e37bb7fd484dfd0", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Metamodellierungs-Architekturdiagramm / Schichten- und Zuordnungsmodell (MOF-orientiert, M2/M1-Abstraktionsebenen mit Serialisierungspfad zur Artefakt-/M0-Ebene).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation des M1-basierten Konfigurationsansatzes für die <em>AUTOSAR Adaptive Platform (Machine Configuration)</em>. Visualisierung der Entkopplung zwischen Konfigurationsdefinition (<code>Definition Side</code>) und konkreter Instanzbelegung (<code>Value Side</code>) auf M1-Ebene bei gleichzeitiger bidirektionaler Konformität zum übergeordneten M2-Metamodell.\n</li><li><strong>Funktionale Einordnung:</strong> Ablösung des starren M2-Schemas (wie aus AUTOSAR Classic ECUC bekannt) für plattformspezifische Maschinenkonfigurationen (u. a. Execution Management, State Management, OS/Plattformressourcen). Ermöglicht hersteller- und funktionsclusterspezifische Parametrierbarkeit ohne Schemaanpassungen des AUTOSAR-Standards.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>M2-Ebene (Metamodell-Ebene):</strong>\n<ul class=\"fig-list\"><li><code>Meta-Model</code>: Das standardisierte AUTOSAR-M2-Metamodell (UML-/XML-Schema-Spezifikation). Definiert die generische Metasprachgrammatik für Definitions- und Wertestrukturen.\n</li></ul>\n</li><li><strong>M1-Ebene (Modellebene):</strong>\n<ul class=\"fig-list\"><li><code>Parameter Definition Side</code>: Instanz des M2-Metamodells. Kapselt die Parameterdeklaration (Funktionscluster-Terminologie, Datentypen, Wertebereiche, domänenspezifische Multiplizitäten und Default-Werte).\n</li><li><code>Parameter Value Side</code>: Instanz des M2-Metamodells. Repräsentiert die konkrete Belegung der Parameter für ein spezifisches Deployment / eine Machine.\n</li></ul>\n</li><li><strong>Persistenz-/Dateiebene (Serialisierung):</strong>\n<ul class=\"fig-list\"><li><code>XML Parameters</code>: Physische ARXML-Dateien der Definitionsseite (Parametertemplate des Stacks/Clusters).\n</li><li><code>XML Values</code>: Physische ARXML-Dateien der Wertebelegungen (maschinenindividuelle Konfigurationsinstanz).\n</li></ul>\n</li><li><strong>Beziehungen &amp; Abhängigkeiten:</strong>\n<ul class=\"fig-list\"><li><code>follows</code> (<code>Parameter Definition Side</code> → <code>Meta-Model</code>): Strukturelle Konformität der Definitionsmetaklassen zum M2-Metamodell.\n</li><li><code>follows</code> (<code>Parameter Value Side</code> → <code>Meta-Model</code>): Strukturelle Konformität der Wertemetaklassen zum M2-Metamodell.\n</li><li><code>Complies to</code> (<code>Parameter Value Side</code> → <code>Parameter Definition Side</code>): Semantische Bindung und Validierungsvertrag; die Werteinstanzen müssen exakt den in der Definition deklarierten Constraints (Typkompatibilität, Restriktionen, Multiplizitäten) entsprechen.\n</li><li><code>Serialized to</code> (M1 → XML): Formale Überführung der In-Memory-Modellinstanzen in ARXML-Dateien.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf (falls zutreffend)</h4>\n<p class=\"fig-p\"><em>Struktur- und Metaebenen-Modell; kein Laufzeitverhalten auf der Zielhardware. Gültig ist der Build- und Konfigurations-Workflow:</em></p>\n<ol class=\"fig-list\"><li><strong>Definitions-Workflow (Stack-/Cluster-Autor):</strong>\n<ul class=\"fig-list\"><li>Deklaration der Konfigurationsparameter unter Nutzung der M2-Grammatik.\n</li><li>Serialisierung der Parametertemplates als <code>XML Parameters</code> (Lieferbestandteil des Adaptive-Core-Stacks / Funktionsclusters).\n</li></ul>\n</li><li><strong>Konfigurations-Workflow (System-/Machine-Integrator):</strong>\n<ul class=\"fig-list\"><li>Instanziierung der Werte im Integrationswerkzeug gemäß M2-Regelsatz (<code>follows</code>).\n</li><li>Abgleich und Bindung gegen die mitgelieferte Definition (<code>Complies to</code>).\n</li><li>Serialisierung der Maschinenbelegung als <code>XML Values</code>.\n</li></ul>\n</li><li><strong>Validierung &amp; Generierung:</strong>\n<ul class=\"fig-list\"><li>Werkzeugseitige Syntaxprüfung gegen das M2-XML-Schema.\n</li><li>Modellvalidator erzwingt die M1-Semantik (<code>Complies to</code>). Bei Constraint-Verletzung (z. B. Multiplizität ≠ Default/Grenzen) bricht die Toolchain ab.\n</li><li>Code- und Manifest-Generatoren transformieren die validierten <code>XML Values</code> in maschinenlesbare Target-Artefakte.\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Konfigurations- &amp; Toolchain-Auswirkung:</strong>\n<ul class=\"fig-list\"><li>Erweiterungen von Konfigurationsparametern für Machine-, OS- oder Plattformdienste erfordern <strong>keinen</strong> M2-Schemawechsel und keine Freigabezyklen des AUTOSAR-Konsortiums.\n</li><li>Tier-1- und OEM-spezifische Erweiterungen (Vendor-Specific Extensions) sind First-Class-Citizens auf M1-Ebene, ohne Bruch der Schema-Rückwärtskompatibilität.\n</li></ul>\n</li><li><strong>Validierungsregeln für Stack-Entwickler:</strong>\n<ul class=\"fig-list\"><li>Ein valider M2-Schema-Check (XSD) garantiert <strong>nicht</strong> die semantische Richtigkeit der Konfiguration. Werkzeuge und Codegeneratoren müssen zwingend eine M1-zu-M1-Semantikprüfung (<code>Complies to</code>) implementieren.\n</li><li>Multiplizitäten sind auf M1-Ebene nicht auf das M2-Standardraster (<code>0..1</code>, <code>0..*</code>) limitiert; anwendungsspezifische Grenzen (z. B. exakt <code>1..4</code>) werden hier verbindlich validiert.\n</li></ul>\n</li><li><strong>Embedded-Target-Relevanz (Adaptive Core):</strong>\n<ul class=\"fig-list\"><li>Weder <code>XML Parameters</code> noch <code>XML Values</code> gelangen direkt auf das Embedded-Target. Sie dienen als Eingangsparameter für Generatoren, die daraus target-spezifische Konfigurationsartefakte erzeugen (z. B. Execution-Manifeste als JSON/BSON, C++-Konfigurations-Header oder Systemd-Service-Dateien).\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-953bb675ccdce272", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Metamodellierungs-Architekturdiagramm / Schichten- und Zuordnungsmodell (MOF-orientiert, M2/M1-Abstraktionsebenen mit Serialisierungspfad zur Artefakt-/M0-Ebene).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation des M1-basierten Konfigurationsansatzes für die <em>AUTOSAR Adaptive Platform (Machine Configuration)</em>. Visualisierung der Entkopplung zwischen Konfigurationsdefinition (<code>Definition Side</code>) und konkreter Instanzbelegung (<code>Value Side</code>) auf M1-Ebene bei gleichzeitiger bidirektionaler Konformität zum übergeordneten M2-Metamodell.\n</li><li><strong>Funktionale Einordnung:</strong> Ablösung des starren M2-Schemas (wie aus AUTOSAR Classic ECUC bekannt) für plattformspezifische Maschinenkonfigurationen (u. a. Execution Management, State Management, OS/Plattformressourcen). Ermöglicht hersteller- und funktionsclusterspezifische Parametrierbarkeit ohne Schemaanpassungen des AUTOSAR-Standards.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>M2-Ebene (Metamodell-Ebene):</strong>\n<ul class=\"fig-list\"><li><code>Meta-Model</code>: Das standardisierte AUTOSAR-M2-Metamodell (UML-/XML-Schema-Spezifikation). Definiert die generische Metasprachgrammatik für Definitions- und Wertestrukturen.\n</li></ul>\n</li><li><strong>M1-Ebene (Modellebene):</strong>\n<ul class=\"fig-list\"><li><code>Parameter Definition Side</code>: Instanz des M2-Metamodells. Kapselt die Parameterdeklaration (Funktionscluster-Terminologie, Datentypen, Wertebereiche, domänenspezifische Multiplizitäten und Default-Werte).\n</li><li><code>Parameter Value Side</code>: Instanz des M2-Metamodells. Repräsentiert die konkrete Belegung der Parameter für ein spezifisches Deployment / eine Machine.\n</li></ul>\n</li><li><strong>Persistenz-/Dateiebene (Serialisierung):</strong>\n<ul class=\"fig-list\"><li><code>XML Parameters</code>: Physische ARXML-Dateien der Definitionsseite (Parametertemplate des Stacks/Clusters).\n</li><li><code>XML Values</code>: Physische ARXML-Dateien der Wertebelegungen (maschinenindividuelle Konfigurationsinstanz).\n</li></ul>\n</li><li><strong>Beziehungen &amp; Abhängigkeiten:</strong>\n<ul class=\"fig-list\"><li><code>follows</code> (<code>Parameter Definition Side</code> → <code>Meta-Model</code>): Strukturelle Konformität der Definitionsmetaklassen zum M2-Metamodell.\n</li><li><code>follows</code> (<code>Parameter Value Side</code> → <code>Meta-Model</code>): Strukturelle Konformität der Wertemetaklassen zum M2-Metamodell.\n</li><li><code>Complies to</code> (<code>Parameter Value Side</code> → <code>Parameter Definition Side</code>): Semantische Bindung und Validierungsvertrag; die Werteinstanzen müssen exakt den in der Definition deklarierten Constraints (Typkompatibilität, Restriktionen, Multiplizitäten) entsprechen.\n</li><li><code>Serialized to</code> (M1 → XML): Formale Überführung der In-Memory-Modellinstanzen in ARXML-Dateien.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\"><em>Struktur- und Metaebenen-Modell; kein Laufzeitverhalten auf der Zielhardware. Gültig ist der Build- und Konfigurations-Workflow:</em></p>\n<ol class=\"fig-list\"><li><strong>Definitions-Workflow (Stack-/Cluster-Autor):</strong>\n<ul class=\"fig-list\"><li>Deklaration der Konfigurationsparameter unter Nutzung der M2-Grammatik.\n</li><li>Serialisierung der Parametertemplates als <code>XML Parameters</code> (Lieferbestandteil des Adaptive-Core-Stacks / Funktionsclusters).\n</li></ul>\n</li><li><strong>Konfigurations-Workflow (System-/Machine-Integrator):</strong>\n<ul class=\"fig-list\"><li>Instanziierung der Werte im Integrationswerkzeug gemäß M2-Regelsatz (<code>follows</code>).\n</li><li>Abgleich und Bindung gegen die mitgelieferte Definition (<code>Complies to</code>).\n</li><li>Serialisierung der Maschinenbelegung als <code>XML Values</code>.\n</li></ul>\n</li><li><strong>Validierung &amp; Generierung:</strong>\n<ul class=\"fig-list\"><li>Werkzeugseitige Syntaxprüfung gegen das M2-XML-Schema.\n</li><li>Modellvalidator erzwingt die M1-Semantik (<code>Complies to</code>). Bei Constraint-Verletzung (z. B. Multiplizität ≠ Default/Grenzen) bricht die Toolchain ab.\n</li><li>Code- und Manifest-Generatoren transformieren die validierten <code>XML Values</code> in maschinenlesbare Target-Artefakte.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Konfigurations- &amp; Toolchain-Auswirkung:</strong>\n<ul class=\"fig-list\"><li>Erweiterungen von Konfigurationsparametern für Machine-, OS- oder Plattformdienste erfordern <strong>keinen</strong> M2-Schemawechsel und keine Freigabezyklen des AUTOSAR-Konsortiums.\n</li><li>Tier-1- und OEM-spezifische Erweiterungen (Vendor-Specific Extensions) sind First-Class-Citizens auf M1-Ebene, ohne Bruch der Schema-Rückwärtskompatibilität.\n</li></ul>\n</li><li><strong>Validierungsregeln für Stack-Entwickler:</strong>\n<ul class=\"fig-list\"><li>Ein valider M2-Schema-Check (XSD) garantiert <strong>nicht</strong> die semantische Richtigkeit der Konfiguration. Werkzeuge und Codegeneratoren müssen zwingend eine M1-zu-M1-Semantikprüfung (<code>Complies to</code>) implementieren.\n</li><li>Multiplizitäten sind auf M1-Ebene nicht auf das M2-Standardraster (<code>0..1</code>, <code>0..*</code>) limitiert; anwendungsspezifische Grenzen (z. B. exakt <code>1..4</code>) werden hier verbindlich validiert.\n</li></ul>\n</li><li><strong>Embedded-Target-Relevanz (Adaptive Core):</strong>\n<ul class=\"fig-list\"><li>Weder <code>XML Parameters</code> noch <code>XML Values</code> gelangen direkt auf das Embedded-Target. Sie dienen als Eingangsparameter für Generatoren, die daraus target-spezifische Konfigurationsartefakte erzeugen (z. B. Execution-Manifeste als JSON/BSON, C++-Konfigurations-Header oder Systemd-Service-Dateien).\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-7e37bb7fd484dfd0", "to": "FIG-953bb675ccdce272", "fr": "R24-11", "tr": "R25-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><strong>Relation <code>Parameter Value Side</code> → <code>Parameter Definition Side</code>:</strong> Beschriftung von „Complies to“ (Großschreibung) auf „complies to“ (Kleinschreibung) korrigiert.\n</li><li><strong>Label <code>M2</code>:</strong> Layout-Korrektur des oberen Bildbeschnitts; die Metamodellebenen-Bezeichnung „M2“ ist nun vollständig sichtbar (im Vorgänger am oberen Bildrand abgeschnitten).\n</li></ul>"}]};
